---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Country select: A searchable select with country codes, currency and keyboard support.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change country-select.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './country-select.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="country-select" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="csx">
  <label class="csx-l">Billing country</label>
  <button class="csx-f" aria-haspopup="listbox" aria-expanded="false"><span class="csx-fl"></span><span class="csx-v"></span><svg class="i xs"><use href="#i-chev-d"/></svg></button>
  <div class="pop csx-pop"><div class="csx-s"><svg class="i xs"><use href="#i-search"/></svg><input class="csx-q" placeholder="Search countries" aria-label="Search countries" spellcheck="false"></div><div class="csx-list" role="listbox"></div></div>
  <span class="muted csx-h">Used for tax and currency</span>
</div>
  </Fragment></div>
</div>
<script>
  import './country-select.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Country select ---------- */
/* the label, the field and the hint, as wide as the other single fields. The list opens from the field (placePop), and the
   field glides up with it so the two sit centred together (centre()). The field's flag, the search's glass and the rows'
   flags share one column 12px in, and the names another; the currencies end 12px in, before the chosen country's tick */
.csx{width:100%;max-width:var(--dm-field-w);margin:0 auto;display:flex;flex-direction:column;gap:6px;position:relative}
.csx-l{font-size:12.5px;font-weight:500}
.csx-f{display:flex;align-items:center;gap:10px;height:var(--dm-field-h);padding:0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:13.5px;text-align:left;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.csx-f{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
/* a dropdown's field steps up its edge while it has the keyboard's focus or its list is open; it takes no ring */
.csx-f:focus-visible{outline:0}
.csx-f:is(:focus-visible,[aria-expanded="true"]){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.csx-v{flex:1}
.csx-f>svg{color:var(--dm-muted);transition:transform .35s var(--dm-ease)}
.csx-f[aria-expanded="true"]>svg{transform:rotate(180deg)}
.csx-fl{display:grid;place-items:center;flex:none;width:20px}
.csx-h{font-size:12px;transition:opacity var(--dm-t-fast) var(--dm-ease)}
/* the open list covers the hint under the field, so the hint steps aside rather than peeking out at the list's corner */
.csx:has(.csx-pop.open) .csx-h{opacity:0}
/* closed, the list is hidden as well as clear (.pop), so Tab passes over its search and its countries */
.csx-pop{left:0;right:0;min-width:0;padding:0 6px 6px}
/* the search is the list's first row: its glass on the flags' column, its words on the names', a hairline under it that
   steps up while it has the focus */
.csx-s{display:flex;align-items:center;gap:10px;height:var(--dm-field-h);margin:0 -6px 6px;padding:0 var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-muted);transition:border-color var(--dm-t-fast)}
.csx-s>svg{margin:0 4px}
.csx-s:has(.csx-q:focus){border-bottom-color:color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.csx-q{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;padding:0;font:inherit;font-size:13px;color:var(--dm-fg)}
.csx-q::placeholder{color:var(--dm-muted)}
.csx-list{max-height:200px;overflow-y:auto;display:flex;flex-direction:column;gap:2px}
.csx-o{display:flex;align-items:center;gap:10px;padding:7px 6px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;text-align:left;flex:none;transition:background var(--dm-t-fast)}
.csx-o.hl{background:var(--dm-row)}
.csx-o .cd{margin-left:auto;font-size:11.5px;color:var(--dm-muted);transition:color var(--dm-t-fast)}
/* on a highlighted row's grey the currency steps up, so it keeps 4.5:1 and APCA Lc 60 in dark mode */
.csx-o.hl .cd{color:var(--dm-fg2)}
/* every row keeps a place for the tick, so the currencies stand in one column */
.csx-o .ck{display:grid;color:var(--dm-accent-fg,var(--dm-accent));visibility:hidden}
.csx-o[aria-selected="true"] .ck{visibility:visible}
.csx-g{font-size:11.5px;color:var(--dm-muted);padding:6px 6px 2px}
/* Clean (owner, 21 Nov: "almost no difference between soft and clean so make it clearer"). The field is a flat dropdown
   trigger: an off-white fill under a hairline that deepens on hover and while its list is open. The list opens from it with
   Clean's scale and fade, in the menus' 22px corners: its search sits in an off-white head strip, "Suggested" is Clean's
   section label, and the rows are 10px with the one gliding highlight (hoverGlide). The flags, the glass and the label stand
   on one column 16px in; the codes end on the content's right edge, 16px in, and the picked row keeps a stronger fill and its
   tick, in the accent (white in dark), in a column of its own just before its code */
:root[data-style="clean"] .csx-f,:root [data-style="clean"] .csx-f,:root [data-style="clean"].csx-f{background:var(--dm-strip);box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .csx-f:hover,:root [data-style="clean"] .csx-f:hover,:root [data-style="clean"].csx-f:hover{background:var(--dm-chip);box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .csx-f:is(:focus-visible,[aria-expanded="true"]),:root [data-style="clean"] .csx-f:is(:focus-visible,[aria-expanded="true"]),:root [data-style="clean"].csx-f:is(:focus-visible,[aria-expanded="true"]){background:var(--dm-chip);box-shadow:var(--dm-btn2-hover)}
:root[data-style="clean"] .csx-f>svg,:root [data-style="clean"] .csx-f>svg,:root [data-style="clean"].csx-f>svg{transition:transform var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .csx-pop,:root [data-style="clean"] .csx-pop,:root [data-style="clean"].csx-pop{border-radius:var(--dm-r-card);padding:0 6px 6px}
:root[data-style="clean"] .csx-s,:root [data-style="clean"] .csx-s,:root [data-style="clean"].csx-s{height:44px;margin:0 -6px 4px;padding:0 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .csx-s:has(.csx-q:focus),:root [data-style="clean"] .csx-s:has(.csx-q:focus),:root [data-style="clean"].csx-s:has(.csx-q:focus){border-bottom-color:var(--dm-line)}
:root[data-style="clean"] .csx-list,:root [data-style="clean"] .csx-list,:root [data-style="clean"].csx-list{gap:2px;max-height:227px}
:root[data-style="clean"] .csx-g,:root [data-style="clean"] .csx-g,:root [data-style="clean"].csx-g{padding:10px 10px 4px;font-size:11.5px;line-height:16px;color:var(--dm-muted)}
:root[data-style="clean"] .csx-o,:root [data-style="clean"] .csx-o,:root [data-style="clean"].csx-o{height:34px;padding:0 10px;border-radius:10px;transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .csx-o[aria-selected="true"],:root [data-style="clean"] .csx-o[aria-selected="true"],:root [data-style="clean"].csx-o[aria-selected="true"]{background:var(--dm-row-on)}
:root[data-style="clean"] .csx-o .ck,:root [data-style="clean"] .csx-o .ck,:root [data-style="clean"].csx-o .ck{order:1;margin-left:auto}
:root[data-style="clean"] .csx-o .cd,:root [data-style="clean"] .csx-o .cd,:root [data-style="clean"].csx-o .cd{order:2;margin-left:8px;min-width:28px;text-align:right}
/* (on the picked row's stronger grey the code steps up, so it keeps 4.5:1) */
:root[data-style="clean"] .csx-o[aria-selected="true"] .cd,:root [data-style="clean"] .csx-o[aria-selected="true"] .cd,:root [data-style="clean"].csx-o[aria-selected="true"] .cd{color:var(--dm-fg2)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, FLAG, I, REDUCE, centre, hoverGlide, placePop, popRoom } from '../core/core.js';
DM.def('country-select', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs')).replace('{search}', I('search','xs'));
  const C = [
    ['United States','US',['#b22234','#fff','#3c3b6e'],1,'USD'],['United Kingdom','GB',['#012169','#fff','#c8102e'],0,'GBP'],['Germany','DE',['#000','#dd0000','#ffce00'],1,'EUR'],['France','FR',['#0055a4','#fff','#ef4135'],0,'EUR'],
    ['Netherlands','NL',['#ae1c28','#fff','#21468b'],1,'EUR'],['Ireland','IE',['#169b62','#fff','#ff883e'],0,'EUR'],['Italy','IT',['#009246','#fff','#ce2b37'],0,'EUR'],['Japan','JP',['#fff','#bc002d','#fff'],0,'JPY'],
    ['Canada','CA',['#d80621','#fff','#d80621'],0,'CAD'],['Spain','ES',['#aa151b','#f1bf00','#aa151b'],1,'EUR'],['Sweden','SE',['#006aa7','#fecc00','#006aa7'],1,'SEK'],['Australia','AU',['#012169','#fff','#e4002b'],0,'AUD']
  ];
  const f = $('.csx-f', r), pop = $('.csx-pop', r), q = $('.csx-q', r), list = $('.csx-list', r), h = $('.csx-h', r);
  let sel = C[1], hi = 0, opts = [];
  const flag = co => `<span class="csx-fl">${FLAG(co[1])}</span>`;
  /* the name and the hint crossfade to the country picked and always end on the latest one, so the name never stays on
     an earlier country while the flag (swapped at once) shows the new one */
  const put = (el, t) => { el._to = t; if (el._t || el.textContent === t) return; el.classList.add('sw', 'out');
    el._t = setTimeout(() => { el._t = 0; el.textContent = el._to; el.classList.remove('out'); }, REDUCE ? 0 : 170); };
  function setSel(co){ sel = co; $('.csx-fl', f).outerHTML = flag(co); put($('.csx-v', f), co[0]); put(h, 'Prices shown in ' + co[4]); }
  function paint(){
    const v = q.value.trim().toLowerCase(); const m = C.filter(co => !v || co[0].toLowerCase().includes(v) || co[1].toLowerCase() === v);
    list.innerHTML = (v ? '' : '<div class="csx-g">Suggested</div>') + m.map(co => `<button class="csx-o" role="option" id="${list.id}-${co[1]}" tabindex="-1" aria-selected="${co === sel}" data-c="${co[1]}">${flag(co)}${co[0]}<span class="cd">${co[4]}</span><span class="ck">${I('check','xs')}</span></button>`).join('') || '<div class="csx-g">No country found</div>';
    opts = $$('.csx-o', list); hi = Math.max(0, opts.findIndex(o => o.dataset.c === sel[1])); move(0);
    opts.forEach((o, i) => { o.onmouseenter = () => { hi = i; move(0); }; o.onclick = () => { setSel(C.find(x => x[1] === o.dataset.c)); close(); }; });
  }
  function move(d){ if (!opts.length){ q.removeAttribute('aria-activedescendant'); return; } hi = (hi + d + opts.length) % opts.length; opts.forEach((o, i) => o.classList.toggle('hl', i === hi)); opts[hi].scrollIntoView({ block:'nearest' }); q.setAttribute('aria-activedescendant', opts[hi].id); }
  // Clean's one hover: a highlight that glides to the row under the pointer or the arrows
  c.offs.push(hoverGlide(list, '.csx-o'));
  list.id = 'csx-l-' + Math.random().toString(36).slice(2, 7); q.setAttribute('role', 'combobox'); q.setAttribute('aria-autocomplete', 'list'); q.setAttribute('aria-expanded', 'true'); q.setAttribute('aria-controls', list.id);
  // the field sits centred on its own, and glides up as the list opens, so the two sit centred together at every moment, as
  // typing narrows the list too. On a page of your own the list opens over the field when the window has no room under the
  // field for it at its tallest (placePop)
  const box = $('.csx', r), full = () => pop.offsetHeight - list.offsetHeight + parseFloat(getComputedStyle(list).maxHeight);
  let up = false;
  const isOpen = () => pop.classList.contains('open');
  const centred = centre(c, box, () => isOpen() && !up ? Math.max(box.offsetHeight, f.offsetTop + f.offsetHeight + 6 + pop.offsetHeight) : box.offsetHeight, [pop]);
  function place(){
    up = false; centred();
    const gy = parseFloat(box.style.getPropertyValue('--dm-gy')) || 0, now = new DOMMatrixReadOnly(getComputedStyle(box).transform).m42, dy = gy - now;
    const room = popRoom(f), b = f.getBoundingClientRect(), below = room.bottom - b.bottom - dy, above = b.top + dy - room.top;
    // (in a demo's stage the list always opens under the field, which glides up to make room for it)
    up = !r.closest('.stage-in') && below < full() + 12 && above > below; if (up) centred();
    f.dataset.popPos = up ? 'up' : 'down'; placePop(f, pop);
    if (up){ pop.style.top = 'auto'; pop.style.bottom = (box.offsetHeight - f.offsetTop + 6) + 'px'; } else pop.style.bottom = '';
  }
  function open(demo){ pop.classList.add('open'); f.setAttribute('aria-expanded', 'true'); q.value = ''; paint(); place(); if (!demo) q.focus({ preventScroll:true }); }
  // on closing, the field waits for the list to fade before it glides back to the middle
  function close(){ if (!isOpen()) return; pop.classList.remove('open'); f.setAttribute('aria-expanded', 'false'); c.later(REDUCE ? 0 : 180, centred); }
  f.onclick = () => isOpen() ? close() : open();
  q.oninput = paint;
  // in the search box the arrows move through the countries and wrap, Enter picks, and Escape closes the list and gives the
  // focus back to the field (Home and End stay with the text)
  q.onkeydown = e => { if (e.key === 'ArrowDown'){ move(1); e.preventDefault(); } else if (e.key === 'ArrowUp'){ move(-1); e.preventDefault(); } else if (e.key === 'Enter'){ e.preventDefault(); if (opts[hi]){ opts[hi].click(); f.focus({ preventScroll:true }); } } else if (e.key === 'Escape'){ e.preventDefault(); close(); f.focus({ preventScroll:true }); } };
  // Tab out of the list closes it
  c.on(pop, 'focusout', e => { if (isOpen() && e.relatedTarget && !pop.contains(e.relatedTarget) && e.relatedTarget !== f) close(); });
  // the field opens the list with the down and up arrows too, or takes the focus into it when it is already open
  c.on(f, 'keydown', e => { if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return; e.preventDefault(); if (isOpen()) q.focus({ preventScroll:true }); else open(); });
  c.on(document, 'pointerdown', e => { if (!r.contains(e.target)) close(); });
  $('.csx-v', f).textContent = sel[0]; f.insertAdjacentHTML('afterbegin', ''); $('.csx-fl', f).outerHTML = flag(sel);
  // the preview's story: open the list, type "ger", and pick Germany, which closes it on the new country. It stops at the
  // visitor's first click or key in the component, so it never types into their search or picks over their choice
  c.later(900, () => c.run(async () => { const on = () => { if (c.mine) throw 'stop'; };
    on(); open(true); await c.wait(500); for (const ch of 'ger'){ on(); q.value += ch; paint(); await c.wait(160); } await c.wait(1100); on(); if (opts[hi]) opts[hi].click(); }));
});
